/**
 * World-Vision / Editorial radar V1.
 * Rule-based PRIORITY SIGNALS, NOT automated fact-checking.
 * No external AI calls or API keys. Human editorial approval required.
 */
const rows = $input.all().map((item) => item.json || {});
const now = Date.now();
const rules = [
  {cat:"Conflits et sécurité", weight:30, terms:/\\b(war|invasion|missile|airstrike|bombing|ceasefire|hostage|coup|attack|attacks|strikes|ukraine|gaza|sudan|iran|russia|nato)\\b/i},
  {cat:"Catastrophes et humanitaire",weight:30,terms:/\\b(earthquake|tsunami|hurricane|floods?|landslide|cyclone|drought|wildfires?|disaster|evacuated|famine|humanitarian|displaced|tropical storm)\\b/i},
  {cat:"Politique mondiale",weight:24,terms:/\\b(president|prime minister|election|parliament|sanctions|summit|united nations|security council|peace deal|resigns?)\\b/i},
  {cat:"Économie et marchés",weight:23,terms:/\\b(inflation|central bank|interest rates?|recession|markets?|stock market|oil prices?|trade war|tariffs?|currency|bankruptcy|jobs report)\\b/i},
  {cat:"Science et technologie",weight:20,terms:/\\b(artificial intelligence|AI|semiconductor|cyberattack|chipmaker|space launch|breakthrough|vaccine|scientists|robotics|data breach)\\b/i},
  {cat:"Santé publique",weight:26,terms:/\\b(outbreak|epidemic|pandemic|ebola|cholera|measles|WHO|public health emergency)\\b/i}
];
const magnitude=/\\b(thousands?|millions?|billions?|dead|deaths?|killed|injured|missing|massive|national|worldwide|global|emergency|historic|record)\\b/i;
const consequences=/\\b(civilians?|families|children|hospitals?|homes?|schools?|refugees?|supply|power outage|prices?|livelihoods?|workers?)\\b/i;
const urgent=/\\b(breaking|now|urgent|confirmed|announces?|warns?|latest|overnight|this morning|today)\\b/i;
const byKey = new Map();
for (const raw of rows) {
  const title = String(raw.title || "").replace(/<[^>]*>/g,"").replace(/\\s+/g," ").trim();
  const url = String(raw.link || raw.guid || "").trim();
  if(!title || !/^https?:\\/\\//i.test(url))continue;
  const description=String(raw.contentSnippet || raw.description || raw.content || "").replace(/<[^>]*>/g," ").replace(/\\s+/g," ").slice(0,450).trim();
  const dateString=raw.isoDate || raw.pubDate || raw.published || "";
  const timestamp=Date.parse(dateString);
  const ageHours=Number.isFinite(timestamp)?(now-timestamp)/3600000:null;
  if(ageHours!==null && (ageHours < -2 || ageHours > 72))continue;
  const combined=title+" "+description;
  const matched=rules.filter(r=>r.terms.test(combined));
  const category=matched.sort((a,b)=>b.weight-a.weight)[0];
  // Priority score is only triage. Journalism requires corroboration.
  let score=20+(category?.weight||0)+(magnitude.test(combined)?15:0)+
    (consequences.test(combined)?10:0)+(urgent.test(title)?8:0);
  if(ageHours!==null){score+=(ageHours<=6?12:ageHours<=24?8:ageHours<=48?3:0)}
  if(!category)score=Math.min(score,47);
  if(/\\b(recipe|celebrity|football|entertainment|lifestyle|horoscope|travel tips|fashion)\\b/i.test(title))
    score=Math.min(score,36);
  score=Math.max(0,Math.min(100,score));
  const source=/news\\.un\\.org/i.test(url)?"ONU":/bbc\\.co\\.uk/i.test(url)?"BBC":"Flux externe";
  const canonicalUrl=url.split("#")[0].replace(/[?&]utm_[^&]*/g,"");
  const key=title.toLocaleLowerCase("en").replace(/[^a-z0-9]+/g," ").trim().slice(0,160);
  if(!key)continue;
  const candidate={
    title,url:canonicalUrl,source,date:dateString||null,age_hours:ageHours===null?null:Math.round(ageHours*10)/10,
    category:category?.cat||"Autres",
    priority_score:score,
    context_excerpt:description,
    editorial_status:"TO_VERIFY",
    requires:["second_independent_source","confirmed_event_date","editorial_approval","media_rights_review"],
    note:"Score heuristique, pas une validation des faits ni une autorisation de diffusion."
  };
  const previous=byKey.get(key);
  if(!previous||score>previous.priority_score)byKey.set(key,candidate);
}
const top=[...byKey.values()].sort((a,b)=>b.priority_score-a.priority_score).slice(0,12);
return top.map(c=>({json:c}));
